'use strict';
/**
 * EC-CALC-1 — Box Fill contract v2: literal, independently derived fixtures.
 *
 * Every expected number below was computed by hand from NEC 2020 Table
 * 314.16(A)/(B) and 314.16(B)(5) (see docs/box-fill-contract.md §4, §7) and
 * is written as a literal. Nothing here imports BF_BOXES or BF_VOL as an
 * oracle, and nothing is generated by the production formula under test.
 */
const { test, describe } = require('node:test');
const assert = require('node:assert');
const { calculateBoxFill, CONTRACT, RULE_BASIS } = require('../src/calc/boxFill');

const v2 = (over) => calculateBoxFill(Object.assign({ contract: 2, ruleBasis: 'NEC2020', numDevices: 0, hasClamps: false, extensionVolume: 0 }, over));

describe('contract identity', () => {
  test('version 2, NEC2020 rule basis, echoed on every ok result', () => {
    assert.strictEqual(CONTRACT, 2); assert.strictEqual(RULE_BASIS, 'NEC2020');
    const r = v2({ boxKey: 'sq_4x2_125', largestWireSize: '14', numConductors: 1, egcCount: 0 });
    assert.strictEqual(r.ok, true); assert.strictEqual(r.contract, 2); assert.strictEqual(r.ruleBasis, 'NEC2020');
  });
});

describe('B/C. audit example — 14 x #14 counted, entering #14 EGCs, 4" square 2-1/8" (30.3)', () => {
  const base = { boxKey: 'sq_4x2_125', largestWireSize: '14', numConductors: 14, egcSize: '14' };
  test('n = 7: conductors 28.0, EGC 3.5, required 31.5 -> OVER, remaining -1.2, max 13', () => {
    const r = v2({ ...base, egcCount: 7 });
    assert.strictEqual(r.ok, true);
    assert.strictEqual(r.conductorVolume, 28.0); assert.strictEqual(r.egcVolume, 3.5); assert.strictEqual(r.usedVolume, 31.5);
    assert.strictEqual(r.fits, false); assert.strictEqual(r.remaining, -1.2); assert.strictEqual(r.maxConductors, 13);
    assert.deepStrictEqual(r.egc, { count: 7, size: '14', allowance: 2.0, factor: 1.75, volume: 3.5 });
  });
  test('n = 4: 30.0 -> FITS (exact equality remains FITS)', () => {
    const r = v2({ ...base, egcCount: 4 });
    assert.strictEqual(r.usedVolume, 30.0); assert.strictEqual(r.fits, true); assert.strictEqual(r.egc.factor, 1);
  });
  test('n = 5: 30.5 -> OVER (a genuinely positive excess remains OVER)', () => {
    const r = v2({ ...base, egcCount: 5 });
    assert.strictEqual(r.usedVolume, 30.5); assert.strictEqual(r.fits, false); assert.strictEqual(r.egc.factor, 1.25);
  });
  test('the old boolean path is not a proof that n=7 was ever received: legacy hasEgc:true now requires review', () => {
    const legacy = calculateBoxFill({ boxKey: 'sq_4x2_125', largestWireSize: '14', numConductors: 14, hasEgc: true });
    assert.strictEqual(legacy.ok, false); assert.strictEqual(legacy.reason, 'EGC_DETAILS_REQUIRED'); assert.strictEqual(legacy.requiresReview, true);
    assert.ok(!('fits' in legacy), 'no affirmative fit');
  });
});

describe('A. EGC boundaries n = 0, 1, 4, 5, 7 for each retained size (literal allowances)', () => {
  const ALLOW = { '14': 2.00, '12': 2.25, '10': 2.50, '8': 3.00, '6': 5.00 };   // Table 314.16(B), hand-copied
  const FACTOR = { 0: 0, 1: 1, 4: 1, 5: 1.25, 7: 1.75 };
  for (const size of Object.keys(ALLOW)) {
    for (const n of [0, 1, 4, 5, 7]) {
      test(`#${size}, n=${n}: EGC volume = ${FACTOR[n]} x ${ALLOW[size]}`, () => {
        const r = v2({ boxKey: 'sq_4_11_16x2_125', largestWireSize: size, numConductors: 1, egcCount: n, egcSize: n ? size : undefined });
        assert.strictEqual(r.ok, true, JSON.stringify(r));
        assert.strictEqual(r.egc.volume, FACTOR[n] * ALLOW[size]); assert.strictEqual(r.egc.factor, FACTOR[n]);
      });
    }
  }
  test('EGC size is independent of the governing size within the domain (#14 EGCs under #10 governing)', () => {
    const r = v2({ boxKey: 'sq_4x2_125', largestWireSize: '10', numConductors: 2, numDevices: 1, egcCount: 6, egcSize: '14' });
    assert.strictEqual(r.conductorVolume, 5.0); assert.strictEqual(r.deviceVolume, 5.0);
    assert.strictEqual(r.egc.volume, 1.5 * 2.0); assert.strictEqual(r.usedVolume, 13.0);
  });
  test('larger count or size never lowers the required EGC volume (monotone)', () => {
    let last = -1;
    for (const n of [0, 1, 2, 3, 4, 5, 6, 7, 8, 12, 20]) { const r = v2({ boxKey: 'sq_4x2_125', largestWireSize: '12', numConductors: 1, egcCount: n, egcSize: n ? '12' : undefined }); assert.ok(r.egc.volume >= last); last = r.egc.volume; }
    last = -1;
    for (const size of ['14', '12', '10', '8', '6']) { const r = v2({ boxKey: 'sq_4_11_16x2_125', largestWireSize: '6', numConductors: 1, egcCount: 5, egcSize: size }); assert.ok(r.egc.volume >= last); last = r.egc.volume; }
  });
  test('zero-count: the size field is irrelevant and ignored, even if invalid', () => {
    for (const egcSize of [undefined, '', '12', 'bogus', 7]) {
      const r = v2({ boxKey: 'sq_4x2_125', largestWireSize: '12', numConductors: 3, egcCount: 0, egcSize });
      assert.strictEqual(r.ok, true, String(egcSize)); assert.deepStrictEqual(r.egc, { count: 0, size: null, allowance: 0, factor: 0, volume: 0 });
    }
  });
  test('invalid/conflicting/over-bound: missing size, unknown size, EGC larger than governing, bad counts', () => {
    const b = { boxKey: 'sq_4x2_125', largestWireSize: '12', numConductors: 3 };
    assert.strictEqual(v2({ ...b, egcCount: 1 }).reason, 'EGC_SIZE_REQUIRED');
    assert.strictEqual(v2({ ...b, egcCount: 1, egcSize: '' }).reason, 'EGC_SIZE_REQUIRED');
    assert.strictEqual(v2({ ...b, egcCount: 1, egcSize: '4' }).reason, 'WIRE_NOT_IN_TABLE');
    assert.strictEqual(v2({ ...b, egcCount: 1, egcSize: '10' }).reason, 'EGC_LARGER_THAN_GOVERNING');
    assert.strictEqual(v2({ ...b, egcCount: 1, egcSize: '12' }).ok, true, 'equal size is fine');
    assert.strictEqual(v2({ ...b }).reason, 'EGC_COUNT_REQUIRED');
    for (const bad of [-1, 1.5, NaN, Infinity, '3', null, true]) assert.ok(!v2({ ...b, egcCount: bad, egcSize: '12' }).ok, String(bad));
    assert.strictEqual(v2({ ...b, egcCount: -1, egcSize: '12' }).reason, 'NEGATIVE_COUNT');
    assert.strictEqual(v2({ ...b, egcCount: 2.5, egcSize: '12' }).reason, 'INVALID_COUNT');
  });
});

describe('D/E. rounding trap and exact comparisons', () => {
  test('10 x #12 + 5 entering #12 EGCs, 22.0 marked + 3.31 added: 25.3125 > 25.31 -> OVER although both display 25.31', () => {
    const r = v2({ boxKey: 'pl_sg_22', largestWireSize: '12', numConductors: 10, egcCount: 5, egcSize: '12', extensionVolume: 3.31 });
    assert.strictEqual(r.requiredVolume, 25.3125); assert.strictEqual(r.availableVolume, 25.31);
    assert.strictEqual(r.usedVolume, 25.31, 'display rounding'); assert.strictEqual(r.boxVolume, 25.31);
    assert.strictEqual(r.fits, false); assert.ok(r.remainingRaw < 0); assert.strictEqual(r.remaining, -0);
  });
  test('R1 display contract: reviewer case (7 #12 EGCs, +4.437) — one shared precision, Total never above Required while OVER', () => {
    const r = v2({ boxKey: 'pl_sg_22', largestWireSize: '12', numConductors: 10, egcCount: 7, egcSize: '12', extensionVolume: 4.437 });
    assert.strictEqual(r.requiredVolume, 26.4375); assert.strictEqual(r.availableVolume, 26.437); assert.strictEqual(r.fits, false);
    assert.deepStrictEqual(r.display, { decimals: 4, required: '26.4375', available: '26.4370', remaining: '-0.0005' });
    assert.ok(Number(r.display.available) < Number(r.display.required), 'the displayed pair agrees with the verdict');
  });
  test('R1 display contract: original 5-EGC trap (+3.31) shows 25.3125 vs 25.3100, remaining -0.0025', () => {
    const r = v2({ boxKey: 'pl_sg_22', largestWireSize: '12', numConductors: 10, egcCount: 5, egcSize: '12', extensionVolume: 3.31 });
    assert.deepStrictEqual(r.display, { decimals: 4, required: '25.3125', available: '25.3100', remaining: '-0.0025' }); assert.strictEqual(r.fits, false);
  });
  test('R1 display contract: exact equality prints at 2 decimals and FITS', () => {
    const r = v2({ boxKey: 'pl_sg_22', largestWireSize: '12', numConductors: 10, egcCount: 7, egcSize: '12', extensionVolume: 4.4375 });
    assert.strictEqual(r.remainingRaw, 0); assert.strictEqual(r.fits, true);
    assert.deepStrictEqual(r.display, { decimals: 2, required: '26.44', available: '26.44', remaining: '0.00' });
  });
  test('R1 display contract: finer near-boundary input (+4.43749) never prints a positive excess as negative zero', () => {
    const r = v2({ boxKey: 'pl_sg_22', largestWireSize: '12', numConductors: 10, egcCount: 7, egcSize: '12', extensionVolume: 4.43749 });
    assert.strictEqual(r.fits, false);
    assert.deepStrictEqual(r.display, { decimals: 5, required: '26.43750', available: '26.43749', remaining: '-0.00001' });
    assert.ok(Number(r.display.remaining) < 0 && Number(r.display.remaining) !== 0);
  });
  test('R1 display contract: the decimal domain is not restricted (7-decimal excess) and float noise stays at 2 decimals', () => {
    const a = v2({ boxKey: 'pl_sg_22', largestWireSize: '12', numConductors: 10, egcCount: 7, egcSize: '12', extensionVolume: 4.4374999 });
    assert.deepStrictEqual(a.display, { decimals: 7, required: '26.4375000', available: '26.4374999', remaining: '-0.0000001' });
    const b = v2({ boxKey: 'sq_4x2_125', largestWireSize: '12', numConductors: 1, egcCount: 0, extensionVolume: 0.1 });
    assert.deepStrictEqual(b.display, { decimals: 2, required: '2.25', available: '30.40', remaining: '28.15' });
    // the contract is deterministic and derived only from the raw fields
    for (const r of [a, b]) { assert.strictEqual(r.display.required, r.requiredVolume.toFixed(r.display.decimals)); assert.strictEqual(r.display.available, r.availableVolume.toFixed(r.display.decimals)); assert.strictEqual(r.display.remaining, r.remainingRaw.toFixed(r.display.decimals)); }
  });
  test('quarter allowances produce 0.0625 in3 increments for #12', () => {
    const a = v2({ boxKey: 'sq_4x2_125', largestWireSize: '12', numConductors: 1, egcCount: 5, egcSize: '12' });
    const b = v2({ boxKey: 'sq_4x2_125', largestWireSize: '12', numConductors: 1, egcCount: 6, egcSize: '12' });
    assert.strictEqual(b.requiredVolume - a.requiredVolume, 0.5625); assert.strictEqual(0.5625 / 9, 0.0625);
  });
  test('inputs are not mutated; results are deterministic and finite', () => {
    const input = { contract: 2, boxKey: 'sq_4x2_125', largestWireSize: '12', numConductors: 5, numDevices: 1, hasClamps: true, egcCount: 6, egcSize: '12', extensionVolume: 1.5 };
    const frozen = JSON.stringify(input);
    const a = calculateBoxFill(input); const b = calculateBoxFill(input);
    assert.strictEqual(JSON.stringify(input), frozen); assert.deepStrictEqual(a, b);
    for (const v of Object.values(a)) if (typeof v === 'number') assert.ok(Number.isFinite(v));
  });
});

describe('F. capacity fixtures — literal Table 314.16(A) values per corrected box', () => {
  const LEDGER = [   // key, literal NEC 2020 Table 314.16(A) volume, old shipped value
    ['sq_4x1_25', 18.0, 21.0], ['sq_4x1_5', 21.0, 25.5], ['sq_4x2_125', 30.3, 30.3],
    ['sq_4_11_16x1_5', 29.5, 42.0], ['sq_4_11_16x2_125', 42.0, 60.0],
    ['oct_4x1_25', 12.5, 15.5], ['oct_4x1_5', 15.5, 21.5], ['oct_4x2_125', 21.5, 30.3],
    ['dev_3x2x1_5', 7.5, 7.5], ['dev_3x2x2', 10.0, 10.0], ['dev_3x2x2_25', 10.5, 10.5], ['dev_3x2x2_5', 12.5, 12.5],
    ['dev_3x2x2_75', 14.0, 14.0], ['dev_3x2x3_5', 18.0, 18.0], ['handy_1_5', 10.3, 10.3], ['handy_1_875', 13.0, 13.0],
  ];
  for (const [key, vol, old] of LEDGER) {
    test(`${key}: engine uses ${vol} in3${old !== vol ? ' (was ' + old + ')' : ''}`, () => {
      const r = v2({ boxKey: key, largestWireSize: '14', numConductors: 0, egcCount: 0 });
      assert.strictEqual(r.availableVolume, vol); assert.strictEqual(r.boxVolume, vol);
    });
  }
  test('capacity-only false FITS: 10 x #12 in sq_4x1_5 is OVER at 21.0 (22.5 needed); it was FITS at 25.5', () => {
    const r = v2({ boxKey: 'sq_4x1_5', largestWireSize: '12', numConductors: 10, egcCount: 0 });
    assert.strictEqual(r.requiredVolume, 22.5); assert.strictEqual(r.fits, false);
    assert.ok(22.5 <= 25.5, 'the old value would have said FITS');
  });
  test('capacity-only false FITS: 20 x #12 in 4-11/16" x 2-1/8" is OVER at 42.0 (45.0 needed); was FITS at 60.0', () => {
    const r = v2({ boxKey: 'sq_4_11_16x2_125', largestWireSize: '12', numConductors: 20, egcCount: 0 });
    assert.strictEqual(r.requiredVolume, 45.0); assert.strictEqual(r.fits, false);
  });
  test('capacity-only false FITS: 12 x #12 in 4" octagon 2-1/8" is OVER at 21.5 (27.0 needed); was FITS at 30.3', () => {
    const r = v2({ boxKey: 'oct_4x2_125', largestWireSize: '12', numConductors: 12, egcCount: 0 });
    assert.strictEqual(r.requiredVolume, 27.0); assert.strictEqual(r.fits, false);
  });
  test('marked presets are unchanged and flagged as marked, not table rows', () => {
    const { BF_BOXES } = require('../src/calc/tables');   // metadata, not the expected-values oracle
    for (const [k, v] of Object.entries(BF_BOXES)) {
      if (k.startsWith('pl_')) { assert.strictEqual(v.kind, 'marked'); assert.ok(/verify box marking/.test(v.source)); }
      // EC-CALC-1B: exact RACO multigang products are a third kind — manufacturer catalog capacity, never a Table 314.16(A) row
      else if (k.startsWith('raco_')) { assert.strictEqual(v.kind, 'listed_product'); assert.strictEqual(v.source, 'RACO_MULTIGANG'); assert.strictEqual(v.status, 'verified'); assert.ok(/^RACO Multigang/.test(v.group)); }
      else { assert.strictEqual(v.kind, 'metal'); assert.ok(/T\.314\.16\(A\)/.test(v.source)); }
    }
    assert.strictEqual(Object.keys(BF_BOXES).filter((k) => k.startsWith('raco_')).length, 10, 'exactly the ten seed products');
  });
});
